INSERT INTO producto (nombre, descripcion, precio, stock, imagen, activo) VALUES('Laptop Lenovo', 'Laptop i7 16GB RAM', 3500.00, 10, 'https://drive.google.com/file/d/10gCtXO9p68CWuC7lPPd5SHMOmOy1gTgJ/view?usp=sharing', true),('Mouse Logitech', 'Mouse inalámbrico', 80.00, 50, 'https://drive.google.com/file/d/1DL4uGOBf8LlQt8ykt8M80bRuNMz6zK7b/view?usp=sharing', true),('Teclado Mecánico', 'Teclado RGB', 250.00, 30, 'https://drive.google.com/file/d/1aatjnMCBRDWSIiyhWC_bnlGnYPyJqP4i/view?usp=sharing', true),('Airpods Pro 3', 'Sumérgete en una experiencia sonora inigualable con los AirPods Pro 3 de APPLE.', 1199.00, 9, 'https://drive.google.com/file/d/1wiNZQq8WELuGVxXZGgrno52H9h36e2H9/view?usp=sharing', true),('Televisor Samsung 65" Crystal Uhd U8000F Smart Tv', 'Observa cada tono de color en toda su gloria original con nuestro procesador avanzado.', 1599.00, 10, 'https://drive.google.com/file/d/1SINLAJdM5r0MXHR367i7z-D8BMZ1EbFN/view?usp=sharing', true),('Nintendo Switch', 'Te presentamos la última consola que se une a la familia Nintendo Switch.', 1419.00, 4, 'https://drive.google.com/file/d/15cZsfEr52fEjIXvBoT4jrnsTRCDc70CO/view?usp=sharing', true),('Galaxy Fit3', 'Con su diseño elegante y ligero, el Galaxy Fit3 se adapta cómodamente a tu rutina de ejercicios.', 159.00, 10, 'https://drive.google.com/file/d/10LARbcS_5HA7JT0flqlwyCsxzBmcgUG6/view?usp=sharing', true);
